// features/documents.feature: "Documents cannot be added to a vendor under review"
import { expect, expectStatus, test } from "../../fixtures";

test.describe("upload vendor documents", () => {
  test(
    "documents cannot be added to a vendor under review",
    { tag: "@DOC-06" },
    async ({ apiAs }) => {
      // Arrange: a member creates a draft vendor with a unique name
      const member = await apiAs("member");
      const uniqueName = `DOC-06 Vendor ${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

      const created = await member.post("/api/vendors", {
        data: {
          name: uniqueName,
          category: "software",
          contact_email: `doc06-${Date.now()}-${Math.random().toString(36).slice(2, 8)}@northwind.test`,
        },
      });
      const vendor = await expectStatus<{ id: string; status: string }>(created, 201);
      expect(vendor.status).toBe("draft");

      // Arrange: move the vendor into review
      const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
      const submittedBody = await expectStatus<{ id: string; status: string }>(submitted, 200);
      expect(submittedBody.status).toBe("in_review");

      // Act: attempt to upload a W-9 to the locked vendor
      const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.txt",
            mimeType: "text/plain",
            buffer: Buffer.from("W-9 placeholder content"),
          },
        },
      });

      // Assert
      const body = await expectStatus<{ error: { code: string } }>(upload, 409);
      expect(body.error.code).toBe("vendor_locked");
    },
  );
});
